15	/*
16	  design · pre-emit critique: P5 H4 E4 S5 R5 V4
17	  K2 Affischen v2, runda 2 — akt A (hero + signaturakt) endast.
18	  Auktoritet: typen (ALU/NIX). Viker: fotot (en dämpad plate, högerspalt), färgen
19	  (ingen accent, fem toner totalt), siffrorna (finns inga i denna akt).
20	  Reference lock: Spring/Summer (primär — krossad affischtyp, femfärgstak, typsatt
21	  klocka i nav) + Indoek (lånad detalj — foto maskat genom bokstävernas öppningar,
22	  A-K2:s bevisade inkScan()-teknik). Inga hex eller typsnitt kopierade rakt av.
23	  Typsnitt: Archivo (display, en variabel familj) + Familjen Grotesk (register).
24	  Roller korsar aldrig. Ordmärket ALU/NIX vid normal bredd (100%); "VI BYGGER
25	  ERT VARUMÄRKE." vid smalare bredd (82%) — samma familjs breddaxel gör kontrasten,
26	  ingen tredje font.
27	*/
28	:root{
29	  /* ---- fem färger, ingen accent ---- */
30	  --paper:  oklch(85% 0.028 135);
31	  --ink:    oklch(22% 0.012 150);
32	  --white:  oklch(98.5% 0.004 120);
33	  --line-1: oklch(74% 0.024 135);
34	  --line-2: oklch(45% 0.02 140);
35	
36	  --font-display: "Archivo", "Helvetica Neue", Arial, sans-serif;
37	  --font-text:    "Familjen Grotesk", "Helvetica Neue", Arial, sans-serif;
38	
39	  --bar: 52px;
40	  --gutter: clamp(20px, 3.2vw, 48px);
41	  --maxw: 1680px;
42	  --poster: clamp(58px, 10.5vw, 200px);
43	  --ease: cubic-bezier(.16,1,.3,1);
44	  --step: cubic-bezier(.2,.8,.2,1);
45	
46	  /* engine tokens: reused, no new hue introduced anywhere */
47	  --sc-canvas: var(--paper);
48	  --sc-surface: var(--white);
49	  --sc-ink: var(--ink);
50	  --sc-ink-soft: var(--line-2);
51	  --sc-accent: var(--ink);
52	  --sc-accent-ink: var(--paper);
53	  --sc-font-display: var(--font-display);
54	  --sc-font-text: var(--font-text);
55	  color-scheme: light;
56	}
