68	a:hover{ text-decoration:underline; text-underline-offset:.2em }
69	:focus-visible{ outline:2px solid var(--ink); outline-offset:3px; border-radius:2px }
70	.sr-only{ position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0 0 0 0); white-space:nowrap; border:0; padding:0; margin:-1px }
