270	  var narrow = narrowMQ.matches;
271	  var skipScroll = reduce || narrow;
272	
273	  var heroActEl = document.getElementById('heroAct');
274	  if (skipScroll && heroActEl){
275	    heroActEl.removeAttribute('data-sc-act');
276	    heroActEl.removeAttribute('data-sc-span');
277	  }
278	  /* Crossing the breakpoint live (rotate, resize a real window) changes which
279	     layout mode is structurally correct; simplest robust fix is a reload
280	     rather than trying to un-mount and re-mount the engine mid-session. */
281	  narrowMQ.addEventListener && narrowMQ.addEventListener('change', function(){ location.reload(); });
282	
283	  var params = new URLSearchParams(location.search);
284	  var preview = params.get('preview'); // calyx | horai | hyperborea | open
285	
286	  /* ---------------- klockan: riktig tid i Stockholm ---------------- */
287	  var clockEl = document.getElementById('clock');
288	  var fmt = new Intl.DateTimeFormat('sv-SE', { timeZone:'Europe/Stockholm', hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false });
289	  function tick(){ var d = new Date(); clockEl.textContent = fmt.format(d); clockEl.setAttribute('datetime', d.toISOString()); }
290	  tick(); setInterval(tick, 1000);
291	
292	  /* ---------------- fönstren: mask ur bläcket, aldrig gissad ---------------- */
293	  var NS = 'http://www.w3.org/2000/svg';
294	  var BASE = 71;
295	  var scan = document.createElement('canvas');
296	  var sc = scan.getContext('2d', { willReadFrequently:true });
297	  var SC = 2;
298	
299	  function inkScan(ch, fam){
300	    var W = 400, H = 400, penX = 100, penY = 260;
301	    scan.width = W; scan.height = H;
302	    sc.clearRect(0,0,W,H); sc.font = '900 ' + (100*SC) + 'px ' + fam; sc.textBaseline = 'alphabetic'; sc.fillStyle = '#000';
303	    sc.fillText(ch, penX, penY);
304	    var d = sc.getImageData(0,0,W,H).data;
305	    var ink = function(x,y){ return d[(y*W+x)*4+3] > 110; };
